import asyncio, json, time
from playwright.async_api import async_playwright
from common import *
results=[]
def check(name, ok, info=''):
    results.append((name, bool(ok))); print(('PASS ' if ok else 'FAIL ') + name + ('' if ok else '  -> ' + str(info)[:400]))
PS_CATS=["object","field","user","assignment","tab","apexClass","apexPage","customPermission","flow","app","connectedApp","customMetadata","customSetting","recordType","agent","externalCredential","externalDataSource","presenceStatus","emailRouting"]
def hdr(label, api, kind, kindId, cats, **k): return dict({"label":label,"apiName":api,"kind":kind,"kindId":kindId,"license":"Salesforce","status":"","activeAssignees":12,"managed":False,"standard":False,"description":"","lastModified":"2026-10-28T09:12:00Z","lastModifiedBy":"Admin","editableCats":cats},**k)
def det(key, header): return {"type":"detail","key":key,"savedAt":now,"refreshing":False,"data":{"header":header,"objects":[],"system":[],"fieldObjects":[]}}
async def main():
  async with async_playwright() as p:
    b=await p.chromium.launch(**launch_args())
    pg=await b.new_page(viewport={"width":1400,"height":860})
    errs=[]; pg.on("pageerror",lambda e: errs.append(str(e)))
    await pg.goto(DARK)
    post=lambda m: pg.evaluate(DELIVER, m)
