    check("L1 an item opening shows only the page placeholder, with what's being read", t['page'] and t['text']=='Reading Sales Operations from the org…' and t['dots']==0 and not t['bar'], t)
    await post(det("permissionSet:1", hdr("Sales Operations","Sales_Operations","Permission Set","permissionSet",PS_CATS))); await pg.wait_for_timeout(40)
