    check("L2 spinner dots are animated", anim=="ps-bounce", anim)
    check("L3 once loaded, no placeholder is left", await pg.locator(".page-skeleton").count()==0)
    # ---- the toggles start where the settings say
    await post({"type":"uiDefaults","onlyEnabledAccess":False,"onlyEnabledSystemPermissions":True,"showAllObjects":True}); await pg.wait_for_timeout(30)
    await pg.click(".nav-item:has-text('System Permissions')"); await pg.wait_for_timeout(20)
    check("D1 System Permissions starts with 'Show only enabled' on (setting)", await pg.is_checked(".toggle:has-text('Show only enabled') input"))
