    await pg.click(".nav-item:has-text('Apex Class Access')"); await pg.wait_for_timeout(20)
    await post({"type":"accessDetail","key":"permissionSet:1","category":"apexClass","savedAt":now,"refreshing":False,"data":{"category":"apexClass","items":[{"name":"LeadService","label":"LeadService","enabled":False,"entityId":"01p1"},{"name":"QuoteService","label":"QuoteService","enabled":True,"entityId":"01p2"}]}}); await pg.wait_for_timeout(30)
    check("D3 access lists start with everything shown (setting off)", "LeadService" in await pg.inner_text("main"))
    await post({"type":"uiDefaults","onlyEnabledAccess":True,"onlyEnabledSystemPermissions":False,"showAllObjects":False}); await pg.wait_for_timeout(30)
