    await post({"type":"accessDetail","key":"permissionSet:1","category":"agent","savedAt":now,"refreshing":False,"data":{"category":"agent","metadata":True,"items":[{"name":"HR_Helper","label":"HR Helper","enabled":False},{"name":"Sales_Coach","label":"Sales Coach","enabled":True}]}}); await pg.wait_for_timeout(30)
    t=await pg.inner_text("main")
