    await post({"type":"profileSettings","key":"profile:1","savedAt":now,"refreshing":False,"data":{"defaultApp":"standard__Sales","apps":["standard__Sales"],"loginFlow":None,"dataCategories":[{"group":"Products","visibility":"ALL","categories":[]}],
      "passwordPolicy":{"fullName":"sales_policy_1","values":{"minimumPasswordLength":"8","passwordExpiration":"90","passwordHistory":"3","passwordComplexity":"1","maxLoginAttempts":"5","lockoutInterval":"15","passwordQuestion":"0","profile":"Custom%3A Sales"}},
      "sessionSetting":None,"appList":[{"name":"standard__Sales","label":"Sales"},{"name":"standard__Service","label":"Service"}],"flowList":[{"name":"Lead_Intake","label":"Lead Intake"}],"groupList":["Products","Regions"]}}); await pg.wait_for_timeout(30)
    t=await pg.inner_text("main")
    check("S2 the settings show", "Default app" in t and "Data category visibility" in t and "Password policy" in t and "uses the org-wide session settings" in t, t[:400])
    await pg.select_option("[data-fid='ps.defaultApp']","standard__Service")
    await pg.select_option("[data-fid='dataCategory:Regions']","ALL")
    await pg.select_option("[data-fid='passwordPolicy:sales_policy_1.minimumPasswordLength']","12"); await pg.wait_for_timeout(20)
    await pg.click(".docked-footer button.brand"); await pg.wait_for_timeout(40)
