    await post({"type":"users","text":"Ana","users":[{"userId":"005A","name":"Ana Lima","username":"ana@example.com","profile":"Custom: Sales"}]}); await pg.wait_for_timeout(30)
    await pg.click(".results button >> nth=0"); await pg.wait_for_timeout(20)
    check("U2 picking a user asks for their access", (await sent("userAccess"))[-1]=={"type":"userAccess","userId":"005A"})
    await post({"type":"userAccess","userId":"005A","data":{"user":{"id":"005A","name":"Ana Lima","username":"ana@example.com","active":True,"profile":"Custom: Sales","license":"Salesforce","role":"Sales Rep"},"licenses":["Sales Cloud Einstein"],
      "sources":[{"permissionSetId":"0PSp","kind":"profile","label":"Custom: Sales","key":"profile:1"},{"permissionSetId":"0PS1","kind":"permissionSet","label":"Sales Operations","key":"permissionSet:1","expires":"2026-12-31"},{"permissionSetId":"0PSg","kind":"group","label":"Sales Team Bundle","key":"group:1"}],
      "objects":[{"name":"Account","flags":{"read":[0,1],"edit":[1]}}],"system":[{"name":"ModifyAllData","label":"Modify All Data","sources":[2]}],"custom":[{"name":"Approve_Quotes","label":"Approve Quotes","sources":[1]}]}}); await pg.wait_for_timeout(30)
    t=await pg.inner_text("main")
    check("U3 the summary shows sources, licences and permissions", all(x in t for x in ["Ana Lima","Sales Rep","Sales Cloud Einstein","until 2026-12-31","Modify All Data","Approve Quotes","High impact"]), t[:600])
