    check("U4 each tick says which sources grant it", title=="Granted by: Custom: Sales, Sales Operations", title)
    await pg.click("button.link:has-text('Account')"); await pg.wait_for_timeout(20)
    check("U5 an object's fields are asked for with every source", (await sent("userFields"))[-1]=={"type":"userFields","userId":"005A","object":"Account","ids":["0PSp","0PS1","0PSg"]})
