    await pg.click(".globalbar button:has-text('Compare')"); await pg.wait_for_timeout(20)
    await pg.select_option("[data-fid='cmp.a']","permissionSet:1"); await pg.select_option("[data-fid='cmp.b']","permissionSet:3"); await pg.wait_for_timeout(20)
